    "example_question_sqls": [
      {
        "id": "520926b858d85c63bb7739ea73b37d8a",
        "question": [
          "Score e consultas mensais do CNPJ 05633259000193"
        ],
        "sql": [
          "SELECT date_trunc('month', consultas_cnpj.data_hora_consulta) AS mes, round(avg(consultas_cnpj.score_pj)) AS score_medio, count(*) AS consultas, count(DISTINCT consultas_cnpj.ispb_consulente) AS participantes_distintos FROM workshop_nuclea_genie_catalog.risco.consultas_cnpj consultas_cnpj WHERE consultas_cnpj.cnpj_consultado = '05633259000193' GROUP BY ALL ORDER BY mes"
        ]
      },
      {
        "id": "c31978f397695bc489849d0cbea72673",
        "question": [
          "CNPJs que compartilham socio, telefone ou dominio"
        ],
        "sql": [
          "SELECT empresas_pj.cpf_socio_administrador, count(*) AS qtd_cnpjs, collect_set(empresas_pj.telefone_contato) AS telefones, collect_set(empresas_pj.dominio_email) AS dominios FROM workshop_nuclea_genie_catalog.cadastro.empresas_pj empresas_pj GROUP BY empresas_pj.cpf_socio_administrador HAVING count(*) > 3 ORDER BY qtd_cnpjs DESC"
        ]
      }
